class ReleaseNotSupported(Exception):
    """ Raised when provided SW release is not supported. """
    def __init__(self, release: str):
        super(ReleaseNotSupported, self).__init__()
        self.release = release

    def __str__(self):
        return f"4G-vDUCNF release: {self.release} is not supported"


class APIRequestError(Exception):
    """ Raised when API request fails. """
    def __init__(self, url, method, response):
        self.response = response
        self.status_code = response.status_code
        self.reason = response.reason
        self.url = url
        self.method = method
        self.body = response.text

    def __str__(self):
        return (f"Request {self.method} {self.url} was not successful, "
                f"Status Code: {self.status_code}, reason: {self.reason}, body: {self.body}")


class RequestTimeoutError(Exception):
    """ Raised when ReadTimeout occurs during API request. """
    def __init__(self, url):
        self.url = url

    def __str__(self):
        return f"Request to {self.url} timed out"


class PlanValidationError(Exception):
    """ Raised when staged plan validation fails. """
    def __str__(self):
        return "Plan validation failed, please check your SCF file"


class AuthenticationError(Exception):
    """ Raised when invalid username or password is provided causing authentication failure. """
    def __init__(self, username, password):
        self.username = username
        self.password = password

    def __str__(self):
        return f"Authentication failed. Invalid username: {self.username} or password: {self.password}"
